let profileDraft=null,profileSelectedChar='',profileSaving=false,friendRoom=null,friendTimer=null,friendBusy=false,friendAnimating=false,friendAnimation=0,friendPendingShot=null,friendResultRevision=-1;
let friendRuleSelected='free',friendPollFailed=false,friendPollFailures=0,friendPollBusy=false;
const profileColors=Object.keys(KanjiAvatarStyle.colors),profileFrames=Object.keys(KanjiAvatarStyle.basicFrames),profileGlows=['none','soft','bright'];
const playerRandomId=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
let playerDeviceId;
