const ownedIconChars=()=>[...new Set(gameState.inventory.map(i=>i.char))];
function normalizedPlayerProfile(value){const chars=ownedIconChars(),name=String(value?.name||'プレイヤー').trim().normalize('NFC'),honorId=KanjiHonors.canUse(value?.honorId,gameState.iconProgress)?value.honorId:'';return{name:Array.from(name).slice(0,16).join('')||'プレイヤー',char:chars.includes(value?.char)?value.char:chars[0]||'落',frame:profileFrames.includes(value?.frame)?value.frame:'plain',color:profileColors.includes(value?.color)?value.color:'gold',glow:profileGlows.includes(value?.glow)?value.glow:'soft',honorId,appearance:KanjiAvatarStyle.normalize(value?.appearance,gameState.iconProgress),presets:Array.from({length:3},(_,n)=>{const original=value?.presets?.[n],v=original&&KanjiHonors.retiredIds.includes(original.honorId)?{...original,honorId:''}:original;return v&&KANJI_DATABASE.some(i=>i.char===v.char)&&(!v.honorId||KanjiHonors.canUse(v.honorId,gameState.iconProgress))?{char:v.char,frame:profileFrames.includes(v.frame)?v.frame:'plain',color:profileColors.includes(v.color)?v.color:'gold',glow:profileGlows.includes(v.glow)?v.glow:'soft',honorId:v.honorId||'',appearance:KanjiAvatarStyle.normalize(v.appearance,gameState.iconProgress)}:null;})};}
let avatarSequence=0;
const avatarObserver=new ResizeObserver(entries=>entries.forEach(({target})=>drawAvatarGlyph(target)));
const avatarInkCache=new Map();
function avatarInkBounds(font,char,fontSize,dpr){const key=font+'|'+char+'|'+dpr;if(avatarInkCache.has(key))return avatarInkCache.get(key);const size=Math.ceil(fontSize*3*dpr),c=document.createElement('canvas');c.width=size;c.height=size;const cx=c.getContext('2d',{willReadFrequently:true});cx.scale(dpr,dpr);cx.font=font;cx.fillStyle='#fff';cx.textBaseline='alphabetic';cx.fillText(char,fontSize,fontSize*2);const pixels=cx.getImageData(0,0,size,size).data;let left=size,right=-1,top=size,bottom=-1;for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(pixels[(y*size+x)*4+3]>64){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}const bounds=right<left?{x:fontSize/2,y:-fontSize/3}:{x:(left+right+1)/2/dpr-fontSize,y:(top+bottom+1)/2/dpr-fontSize*2};if(avatarInkCache.size>=300)avatarInkCache.delete(avatarInkCache.keys().next().value);avatarInkCache.set(key,bounds);return bounds;}
function drawAvatarGlyph(el){const c=el.querySelector('canvas'),r=el.getBoundingClientRect();if(!c||!r.width||!r.height)return;const dpr=Math.min(3,devicePixelRatio||1),style=getComputedStyle(el),w=el.clientWidth,h=el.clientHeight;if(!w||!h)return;c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);const cx=c.getContext('2d');cx.scale(dpr,dpr);const font=`${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;cx.font=font;cx.textAlign='left';cx.textBaseline='alphabetic';const char=c.textContent,bounds=avatarInkBounds(font,char,parseFloat(style.fontSize),dpr),x=w*.5-bounds.x,y=h*.5-bounds.y;cx.fillStyle=style.color;
 if(['gold','silver'].includes(el.dataset.finish)){const silver=el.dataset.finish==='silver',g=cx.createLinearGradient(0,h*.25,w,h*.75),stops=silver?['#a6b4c5','#f8fafc','#b7c4d3','#eef2f6']:['#b18c4d','#f9e4ac','#c5a56a','#efd7a1'];stops.forEach((v,n)=>g.addColorStop(n/3,v));cx.fillStyle=g;}
 if(el.dataset.finish==='emboss'){cx.shadowColor=el.dataset.backgroundTone==='navy'||el.dataset.backgroundTone==='black'?'#ffffff66':'#00000055';cx.shadowOffsetX=.65;cx.shadowOffsetY=.65;cx.shadowBlur=.5;}else if(el.dataset.glow!=='none'){cx.shadowColor=style.color;cx.shadowBlur=el.dataset.glow==='bright'?3:1.3;}
 cx.fillText(char,x,y);c.dataset.centerX='.5';c.dataset.centerY='.5';}
window.refreshAvatarFont=()=>{avatarInkCache.clear();document.querySelectorAll('.player-avatar').forEach(drawAvatarGlyph);};
const avatarMotionObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{for(const entry of entries)entry.target.dataset.motionPaused=String(!entry.isIntersecting);}):null;
const observedMotionAvatars=new WeakSet();
function observeAvatarMotion(el){if(!avatarMotionObserver||observedMotionAvatars.has(el))return;observedMotionAvatars.add(el);avatarMotionObserver.observe(el);}
if(typeof MutationObserver==='function'&&avatarMotionObserver)new MutationObserver(records=>{for(const record of records)for(const removed of record.removedNodes){if(removed.nodeType!==1||removed.isConnected)continue;for(const el of [removed,...removed.querySelectorAll('.player-avatar')]){avatarMotionObserver.unobserve(el);observedMotionAvatars.delete(el);}}}).observe(document.body,{childList:true,subtree:true});
document.addEventListener('visibilitychange',()=>{document.documentElement.dataset.avatarPaused=String(document.hidden);});
function paintPlayerAvatar(el,p){if(!el)return;const honor=KanjiHonors.get(p.honorId),a=KanjiAvatarStyle.normalize(p.appearance);let glyph=el.querySelector('canvas');if(!glyph){glyph=document.createElement('canvas');glyph.className='avatar-glyph';glyph.setAttribute('aria-hidden','true');const surface=document.createElement('span');surface.className='avatar-surface';surface.setAttribute('aria-hidden','true');el.replaceChildren(surface,glyph);if(el.id||el.hasAttribute('data-player-avatar'))avatarObserver.observe(el);}
 glyph.textContent=p.char||'漢';el.dataset.frame=p.frame||'plain';el.dataset.color=p.color||'gold';el.dataset.glow=p.glow||'none';for(const [key,value]of Object.entries(a))el.dataset[key]=value;
 const main=KanjiAvatarStyle.colors[p.color]?.[1]||KanjiAvatarStyle.colors.gold[1],frameColor=a.frameTone==='signature'?(honor?KanjiAvatarStyle.accent(honor.id):main):KanjiAvatarStyle.colors[a.frameTone][1];el.style.setProperty('--avatar-color',main);el.style.setProperty('--frame-color',frameColor);el.style.setProperty('--glyph-color',a.glyphColor==='match'?main:KanjiAvatarStyle.colors[a.glyphColor][1]);
 if((el.dataset.honor||'')!==(honor?.id||'')){el.querySelector('.avatar-frame')?.remove();if(honor){el.insertAdjacentHTML('beforeend',KanjiAvatarStyle.frameSvg(honor.id,'avatar-metal-'+(++avatarSequence)));el.dataset.honor=honor.id;}else delete el.dataset.honor;}
 let basicOrbit=el.querySelector('.avatar-orbit-layer');if(honor){basicOrbit?.remove();delete el.dataset.orbitShape;}else if(!basicOrbit||el.dataset.orbitShape!==p.frame){basicOrbit?.remove();el.insertAdjacentHTML('beforeend',KanjiAvatarStyle.orbitSvg(p.frame));el.dataset.orbitShape=p.frame;}delete el.dataset.honorAtlas;el.style.removeProperty('--honor-position');el.querySelector('.avatar-badge')?.remove();
 observeAvatarMotion(el);el.setAttribute('aria-label',honor?`${p.char||'漢'}：${honor.name}の装飾枠`:`${p.char}のアイコン`);drawAvatarGlyph(el);requestAnimationFrame(()=>drawAvatarGlyph(el));}
function paintPlayerName(el,p,label=p.name){if(!el)return;el.textContent=label;const a=KanjiAvatarStyle.normalize(p.appearance);if(a.badge==='none')return;const badge=document.createElement('span');badge.className='player-name-badge';badge.dataset.glow=p.glow||'none';const reward=KanjiAvatarStyle.badges.find(b=>b.id===a.badge);badge.dataset.medalTier=reward?.tier===undefined?'legacy':String(reward.tier);badge.innerHTML=KanjiAvatarStyle.badgeSvg(a.badge);badge.style.color=KanjiAvatarStyle.colors[p.color]?.[1]||'#fbbf24';badge.setAttribute('role','img');badge.setAttribute('aria-label',KanjiAvatarStyle.badges.find(b=>b.id===a.badge)?.name||'勲章');el.append(badge);}
function renderPlayerIdentity(){gameState.playerProfile=normalizedPlayerProfile(gameState.playerProfile);const p=gameState.playerProfile;document.querySelectorAll('[data-player-avatar]').forEach(el=>paintPlayerAvatar(el,p));paintPlayerName(document.getElementById('profile-card-name'),p);paintPlayerName(document.getElementById('battle-self-name'),p);document.getElementById('header-profile').setAttribute('aria-label',`${p.name}：プレイヤー名とアイコンを設定`);const n=KanjiHonors.catalogue.filter(i=>KanjiHonors.canUse(i.id,gameState.iconProgress)).length;document.getElementById('profile-honor-count').textContent=`豪華枠 ${n} / ${KanjiHonors.catalogue.length} 解放`;}
async function playerApi(path,method='GET',body){
 await ensureGuestSession();const headers={'X-Kanji-Device':playerDeviceId,...guestHeaders(),...(body?{'Content-Type':'application/json'}:{})};
 const perform=async()=>{const response=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers,...(body?{body:JSON.stringify(body)}:{})});let value;try{value=await response.json();}catch{throw Object.assign(Error('接続できません。Safariで再読み込みしてお試しください。'),{status:response.status});}if(response.status===401&&typeof setOnlineAuthenticated==='function')setOnlineAuthenticated(false);if(!response.ok)throw Object.assign(Error(value.error||'接続できません。もう一度お試しください。'),{status:response.status,code:value.code,retryAfter:KanjiNetwork.retryAfter(response)});return value;};
 if(method==='GET')return KanjiNetwork.read(JSON.stringify([path,headers]),perform);KanjiNetwork.invalidate();try{return await perform();}finally{KanjiNetwork.invalidate();}
}
function acceptHonorProgress(value){KanjiPromotions.inherit(gameState,value);gameState.iconProgress=KanjiHonors.merge(KanjiHonors.fromState(gameState,KANJI_DATABASE),value);gameState.specialTrialLevelBest=Math.max(gameState.specialTrialLevelBest||0,gameState.iconProgress.highestTrialLevel);gameState.specialTrialWins=Math.max(gameState.specialTrialWins||0,gameState.iconProgress.trialWins);gameState.specialTrialBest=Math.max(gameState.specialTrialBest||0,gameState.iconProgress.bestTrialStreak);try{KanjiTrialThemes.restore(gameState,localStorage);}catch{}}
function queueHonorSync(){if(!honorSyncReady)return;clearTimeout(honorSyncTimer);honorSyncTimer=setTimeout(syncHonorProgress,400);}
async function syncHonorProgress(){if(honorSyncBusy||!honorSyncReady)return;const snapshot=JSON.stringify(gameState.iconProgress);if(snapshot===honorPersisted)return;honorSyncBusy=true;let succeeded=false;try{const result=await playerApi('/api/achievements','POST',{progress:gameState.iconProgress,profile:normalizedPlayerProfile(gameState.playerProfile)});acceptHonorProgress(result.achievementProgress);honorPersisted=JSON.stringify(result.achievementProgress);saveState();if(profileDraft)renderProfileHonors();succeeded=true;}catch{}finally{honorSyncBusy=false;if(succeeded&&JSON.stringify(gameState.iconProgress)!==honorPersisted)queueHonorSync();}}
function initializePlayerProfile(){gameState.iconProgress=KanjiHonors.fromState(gameState,KANJI_DATABASE);renderPlayerIdentity();const cached=JSON.stringify(gameState.playerProfile);playerApi('/api/profile').then(result=>{acceptHonorProgress(result.achievementProgress);if(result.profile&&JSON.stringify(gameState.playerProfile)===cached&&!profileDraft){gameState.playerProfile=normalizedPlayerProfile(result.profile);}honorPersisted=JSON.stringify(KanjiHonors.progress(result.achievementProgress));saveState();honorSyncReady=true;queueHonorSync();if(typeof initializeChallengeRankings==='function')initializeChallengeRankings();}).catch(()=>{honorSyncReady=true;queueHonorSync();if(typeof initializeChallengeRankings==='function')initializeChallengeRankings();});let code;try{code=sessionStorage.getItem('kanji_friend_room');}catch{}if(code&&/^[A-Z2-9]{8}$/.test(code))setTimeout(()=>resumeFriendRoom(code),300);}
function pausePlayerOverlay(){cancelDrag();if(runner)runner.enabled=false;}
function resumePlayerEngine(){if(runner)runner.enabled=!soloBattlePending&&battleMode!=='friend'&&!document.hidden&&!document.getElementById('screen-battle').classList.contains('hidden')&&!document.querySelector('[id^="modal-"]:not(.hidden)');}
window.openPlayerProfile=()=>{gameState.iconProgress=KanjiHonors.fromState(gameState,KANJI_DATABASE);profileDraft=normalizedPlayerProfile(gameState.playerProfile);profileSelectedChar=profileDraft.char;profileSelectedHonor=profileDraft.honorId;document.getElementById('player-name').value=profileDraft.name;for(const kind of ['frame','color','glow'])document.getElementById('profile-'+kind).value=profileDraft[kind];initializeAvatarControls();applyAvatarControls(profileDraft);renderAvatarPresets();document.getElementById('profile-character-search').value='';document.getElementById('profile-save-status').textContent='';pausePlayerOverlay();document.getElementById('modal-profile').classList.remove('hidden');selectProfileTab('character');document.querySelector('#modal-profile .profile-shell').scrollTop=0;renderProfileCharacters();renderProfileHonors();previewPlayerProfile();};
window.closePlayerProfile=()=>{if(profileSaving)return;profileDraft=null;document.getElementById('modal-profile').classList.add('hidden');resumePlayerEngine();document.getElementById('header-profile').focus();};
window.renderProfileCharacters=()=>{const query=document.getElementById('profile-character-search').value.trim(),box=document.getElementById('profile-character-picker'),chars=ownedIconChars().filter(c=>!query||c.includes(query));box.replaceChildren();for(const char of chars){const b=document.createElement('button');b.type='button';b.className='profile-character-choice kanji-font';b.textContent=char;b.dataset.profileChar=char;b.setAttribute('aria-label',`「${char}」をアイコンにする`);b.setAttribute('aria-pressed',String(profileSelectedChar===char));b.onclick=()=>{profileSelectedChar=char;previewPlayerProfile();renderProfileCharacters();renderProfileHonors();};box.append(b);}if(!chars.length)box.textContent='該当する所持文字がありません。';};
function renderProfileHonors(){if(typeof renderProfileMedals==='function')renderProfileMedals();const box=document.getElementById('profile-honor-picker');box.replaceChildren();for(const group of KanjiHonors.groups()){const visibleItems=group.items.filter(i=>(i.key!=='highestOnlineRP'||KanjiHonors.canUse(i.id,gameState.iconProgress))&&KanjiAbilityGuide.matches(document.getElementById('profile-honor-filter')?.value,KanjiHonors.canUse(i.id,gameState.iconProgress),i,gameState.iconProgress,gameState,KANJI_DATABASE));if(!visibleItems.length)continue;const section=document.createElement('section');section.className='profile-honor-group';const title=document.createElement('h4');title.textContent=group.name;const grid=document.createElement('div');grid.className='profile-honor-grid';section.append(title,grid);box.append(section);for(const item of visibleItems){const unlocked=KanjiHonors.canUse(item.id,gameState.iconProgress),b=document.createElement('button');b.type='button';b.className='profile-honor-choice';b.dataset.honorId=item.id;b.disabled=!unlocked;b.setAttribute('aria-pressed',String(profileSelectedHonor===item.id));b.setAttribute('aria-label',`${item.name}：${item.condition}（${unlocked?'解放済み':'未解放'}）`);const art=document.createElement('span');art.className='player-avatar large';paintPlayerAvatar(art,{...profileDraft,char:profileSelectedChar,honorId:item.id,appearance:{...profileDraft.appearance,motion:'still'}});const name=document.createElement('strong');name.textContent=item.name;const condition=document.createElement('span');condition.textContent=item.condition;const status=document.createElement('small');status.textContent=unlocked&&!/^codex-jis-/.test(item.id)?'解放済み・選択できます':(/^codex-jis-/.test(item.id)?(()=>{const jis=Number(item.id.slice(-1)),bases=KANJI_DATABASE.filter(i=>i.jis===jis),found=new Set([...(gameState.characterDiscoveries||[]),...gameState.inventory.map(i=>i.char)]);return '発見 '+bases.filter(i=>found.has(i.char)).length.toLocaleString()+' / '+bases.length.toLocaleString()+' 種類'+(unlocked?'・解放済み':'');})():KanjiHonors.status(item,gameState.iconProgress));if(['collectedElements','collectedFish'].includes(item.key)){status.textContent=KanjiHonors.status(item,gameState.iconProgress);}if(item.key==='highestCharacterWins'){const leader=Object.entries(gameState.playProgress?.usage||{}).sort((a,b)=>(b[1].honorWins||0)-(a[1].honorWins||0))[0];status.textContent=KanjiHonors.status(item,gameState.iconProgress)+(leader&&leader[1].honorWins?'・最多勝利「'+leader[0]+'」':'');}b.append(art,name,condition,status);b.onclick=()=>{if(!KanjiHonors.canUse(item.id,gameState.iconProgress))return;profileSelectedHonor=item.id;previewPlayerProfile();renderProfileCharacters();renderProfileHonors();};grid.append(b);}}if(!box.children.length)box.textContent='この条件に合う枠はありません。';}
window.previewPlayerProfile=()=>{if(!profileDraft)return;profileDraft={...profileDraft,appearance:readAvatarControls(),name:document.getElementById('player-name').value.trim(),char:profileSelectedChar,frame:document.getElementById('profile-frame').value,color:document.getElementById('profile-color').value,glow:document.getElementById('profile-glow').value,honorId:profileSelectedHonor};paintPlayerAvatar(document.getElementById('profile-preview-icon'),profileDraft);paintPlayerName(document.getElementById('profile-preview-name'),profileDraft,profileDraft.name||'名前を入力');document.getElementById('profile-selected-character').textContent=profileSelectedHonor?`選択中：「${profileSelectedChar}」＋${KanjiHonors.get(profileSelectedHonor)?.name||''}`:`選択中：「${profileSelectedChar}」`;document.querySelectorAll('#profile-honor-picker .player-avatar').forEach(el=>paintPlayerAvatar(el,{...profileDraft,honorId:el.parentElement.dataset.honorId,appearance:{...profileDraft.appearance,motion:'still'}}));document.getElementById('profile-frame-help').textContent=profileSelectedHonor?'豪華枠を選択中です。通常の形に戻すときは「通常の枠を使う」を押してください。':'';document.getElementById('avatar-glyphColor').disabled=['gold','silver'].includes(profileDraft.appearance.finish);renderProfileMotionNote();if(typeof renderProfileMedals==='function')renderProfileMedals();document.getElementById('profile-decoration').disabled=false;document.getElementById('profile-frame').disabled=!!profileSelectedHonor;document.getElementById('btn-profile-basic-frame').setAttribute('aria-pressed',String(!profileSelectedHonor));};
window.useBasicProfileFrame=()=>{profileSelectedHonor='';previewPlayerProfile();renderProfileCharacters();renderProfileHonors();};
window.savePlayerProfile=async()=>{if(profileSaving)return;previewPlayerProfile();const p={...profileDraft},status=document.getElementById('profile-save-status');if(!p.name||Array.from(p.name).length>16||/[\x00-\x1f\x7f<>]/.test(p.name)){status.textContent='名前は1〜16文字で入力してください。';return;}if(!ownedIconChars().includes(p.char)||p.honorId&&!KanjiHonors.canUse(p.honorId,gameState.iconProgress)){status.textContent='解放済みのアイコンか、所持文字を選んでください。';return;}profileSaving=true;document.getElementById('btn-profile-save').disabled=true;status.textContent='保存中…';try{const result=await playerApi('/api/profile','PUT',{...p,achievementProgress:gameState.iconProgress});acceptHonorProgress(result.achievementProgress);honorPersisted=JSON.stringify(result.achievementProgress);gameState.playerProfile=normalizedPlayerProfile(result.profile);if(JSON.stringify(profileDraft)===JSON.stringify(p)){profileDraft=structuredClone(gameState.playerProfile);renderAvatarPresets();}renderPlayerIdentity();saveState();status.textContent='保存しました。';if(typeof loadLeaderboard==='function')loadLeaderboard();}catch(error){if(error.status===401){gameState.playerProfile=p;renderPlayerIdentity();saveState();status.textContent='この端末に保存しました。ゲストの再接続後にフレンド・オンライン対戦へ反映できます。';}else status.textContent=error.message+' 入力した設定はこの画面に残っています。';}finally{profileSaving=false;document.getElementById('btn-profile-save').disabled=false;}};
function initializeAvatarControls(){const option=(value,label,disabled=false)=>{const o=document.createElement('option');o.value=value;o.textContent=label;o.disabled=disabled;return o;},S=KanjiAvatarStyle;document.getElementById('profile-frame').replaceChildren(...Object.entries(S.basicFrames).map(([k,name])=>option(k,name)));document.getElementById('profile-color').replaceChildren(...Object.entries(S.colors).map(([k,[name]])=>option(k,name)));for(const [key,items]of Object.entries({background:S.backgrounds,finish:S.finishes,motion:S.motions,backgroundTone:S.tones,glyphColor:{match:'基本色',...Object.fromEntries(Object.entries(S.colors).map(([k,v])=>[k,v[0]]))},frameTone:{signature:'おすすめ色',...Object.fromEntries(Object.entries(S.colors).map(([k,v])=>[k,v[0]]))}}))document.getElementById('avatar-'+key).replaceChildren(...Object.entries(items).map(([k,name])=>option(k,name)));document.getElementById('avatar-badge').replaceChildren(...S.badges.map(b=>option(b.id,b.name+(!S.badgeUnlocked(b.id,gameState.iconProgress)?'（未解放）':''),!S.badgeUnlocked(b.id,gameState.iconProgress))));}
function applyAvatarControls(p){for(const kind of ['frame','color','glow'])document.getElementById('profile-'+kind).value=p[kind];const a=KanjiAvatarStyle.normalize(p.appearance,gameState.iconProgress);for(const [key,value]of Object.entries(a))document.getElementById('avatar-'+key).value=value;}
function readAvatarControls(){return KanjiAvatarStyle.normalize(Object.fromEntries(Object.keys(KanjiAvatarStyle.defaults).map(key=>[key,document.getElementById('avatar-'+key).value])),gameState.iconProgress);}
function renderAvatarPresets(){const box=document.getElementById('avatar-presets');box.replaceChildren();for(let n=0;n<3;n++){const p=profileDraft?.presets?.[n],slot=document.createElement('div');slot.className='avatar-preset';const title=document.createElement('strong');title.textContent='お気に入り '+(n+1);slot.append(title);if(p){const art=document.createElement('span');art.className='player-avatar large';paintPlayerAvatar(art,{...p,appearance:{...p.appearance,motion:'still'}});slot.append(art);}else{const empty=document.createElement('span');empty.className='avatar-preset-empty';empty.textContent='未登録';slot.append(empty);}const load=document.createElement('button'),save=document.createElement('button');load.type=save.type='button';load.textContent='呼び出す';load.disabled=!p;load.dataset.presetLoad=n;load.onclick=()=>loadAvatarPreset(n);save.textContent=p?'今のアイコンで上書き':'今のアイコンを登録';save.dataset.presetSave=n;save.onclick=()=>saveAvatarPreset(n);slot.append(load,save);box.append(slot);}}
window.saveAvatarPreset=n=>{if(!profileDraft||profileSaving||!Number.isInteger(n)||n<0||n>2)return;previewPlayerProfile();const {char,frame,color,glow,honorId,appearance}=profileDraft;profileDraft.presets=profileDraft.presets||[null,null,null];profileDraft.presets[n]=structuredClone({char,frame,color,glow,honorId,appearance});renderAvatarPresets();document.getElementById('profile-save-status').textContent=`お気に入り${n+1}に登録しました。「設定を保存」で確定します。`;};
window.loadAvatarPreset=n=>{const p=profileDraft?.presets?.[n];if(!p||profileSaving)return;if(!ownedIconChars().includes(p.char)){document.getElementById('profile-save-status').textContent=`「${p.char}」を現在所持していません。もう一度入手すると呼び出せます。`;return;}if(p.honorId&&!KanjiHonors.canUse(p.honorId,gameState.iconProgress))return;profileDraft={...profileDraft,...structuredClone(p)};profileSelectedChar=p.char;profileSelectedHonor=p.honorId;applyAvatarControls(profileDraft);previewPlayerProfile();renderProfileCharacters();renderProfileHonors();document.getElementById('profile-save-status').textContent=`お気に入り${n+1}を呼び出しました。`;};
window.selectProfileTab=id=>{if(!['character','frame','style','presets'].includes(id))return;document.querySelectorAll('[data-profile-tab]').forEach(b=>{const selected=b.dataset.profileTab===id;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;document.getElementById('profile-panel-'+b.dataset.profileTab).hidden=!selected;});document.getElementById('profile-editor-body').scrollTop=0;requestAnimationFrame(()=>document.querySelectorAll('#modal-profile .avatar-glyph').forEach(c=>drawAvatarGlyph(c.parentElement)));};
document.querySelector('.profile-tabs').addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-profile-tab]')],index=tabs.indexOf(e.target);if(index<0||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectProfileTab(tabs[next].dataset.profileTab);tabs[next].focus();});
const profileReducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function renderProfileMotionNote(){const motion=profileDraft?.appearance?.motion||'still',note=document.getElementById('avatar-motion-note');note.textContent=motion!=='still'&&profileReducedMotion.matches?'端末の「視差効果を減らす」設定に合わせて、動きを静止表示しています。':motion==='orbit'?'薄い光が枠を包み、色と濃淡がゆっくり変わります。':motion==='dust'?'小さな光の粒が、枠の周りをゆっくり漂います。':motion==='pulse'?'枠の光が呼吸するようにゆっくり強まります。':motion==='comet'?'明るい先頭から滑らかに薄くなる光が、枠の輪郭を一周し続けます。':motion==='shimmer'?'丸い光と細い十字の輝きが、宝石のように時間差できらめきます。':'';note.hidden=!note.textContent;}
profileReducedMotion.addEventListener('change',()=>{if(profileDraft)renderProfileMotionNote();});
function friendEffectiveRule(){return friendRoom?.mode==='friend'?KanjiOnlineRules.roomRule(friendRoom):friendRuleSelected;}
function renderFriendRules(){const rule=friendEffectiveRule(),select=document.getElementById('friend-rule');select.value=rule;select.disabled=friendBusy||!!friendRoom;document.getElementById('friend-rule-note').textContent=KanjiOnlineRules.description(rule)+(friendRoom?'（この部屋のルール）':'');}
window.setFriendRule=value=>{if(friendBusy||friendRoom||!KanjiOnlineRules.validRule(value))return;friendRuleSelected=value;renderFriendRules();renderFriendDeckSummary();};
function friendRoster(){const setup=resolvedFriendSetup();if(setup.items.length!==3)throw Error('対戦用の編成で文字を3体選んでください。');return {items:setup.items,formation:setup.formation};}
function setFriendStatus(text){document.getElementById('friend-lobby-status').textContent=text;document.getElementById('friend-turn-status').textContent=text;}
function setFriendBusy(value){friendBusy=value;for(const id of ['btn-friend-create','btn-friend-join','btn-friend-leave','btn-friend-rematch','btn-friend-unready','btn-result-room-exit','btn-prepare-room'])document.getElementById(id).disabled=value;document.getElementById('btn-friend-deck').disabled=value||friendRoom?.status==='playing';document.getElementById('btn-friend-next').disabled=value||!!friendRoom?.ready?.[friendRoom?.side];renderFriendRules();renderFriendDirectory();if(friendRoom?.status==='preparing'){const disabled=value||preparationBusy||friendRoom.departed;document.getElementById('btn-battle-start').disabled=!!disabled;document.getElementById('btn-prepare-edit').disabled=!!disabled;}}
function rememberFriendCode(code){try{if(code)sessionStorage.setItem('kanji_friend_room',code);else sessionStorage.removeItem('kanji_friend_room');}catch{}}
window.openFriendLobby=()=>{pausePlayerOverlay();document.getElementById('modal-friends').classList.remove('hidden');setFriendLobbyTab('match');renderFriendLobby();loadFriendList();loadFriendSetup().catch(error=>setFriendStatus(error.message));};
window.closeFriendLobby=()=>{document.getElementById('modal-friends').classList.add('hidden');clearTimeout(friendListTimer);resumePlayerEngine();document.getElementById('btn-friend-lobby').focus();};
function renderFriendLobby(){renderFriendRules();const room=friendRoom;const exit=document.getElementById('btn-friend-leave');exit.hidden=!room||room.mode==='online'&&['preparing','playing'].includes(room.status)&&!room.departed;exit.textContent=room?.status==='playing'?'退出（敗北）':'部屋から退出';document.getElementById('friend-lobby-actions').hidden=!!room;document.getElementById('friend-room-info').hidden=!room;document.getElementById('btn-friend-deck').disabled=friendBusy||room?.status==='playing'||room?.mode!=='online'&&!!room?.ready?.[room.side];renderFriendDeckSummary();if(!room){setFriendStatus('部屋を作るか、友だちの合言葉を入力してください。');return;}document.getElementById('friend-current-code').textContent=room.code;document.getElementById('friend-round-label').textContent=`第${room.round||1}戦・${KanjiOnlineRules.label(KanjiOnlineRules.roomRule(room))}`;document.getElementById('friend-room-code').value=room.code;document.getElementById('btn-friend-board').hidden=!room.state&&room.status!=='preparing';document.getElementById('btn-friend-board').textContent=room.status==='preparing'?'対局の準備に戻る':'盤面に戻る';const box=document.getElementById('friend-players');box.replaceChildren();for(const [n,player]of [room.host,room.guest].entries()){const row=document.createElement('div');row.className='friend-player-row';if(player){const icon=document.createElement('span');icon.className='player-avatar large';paintPlayerAvatar(icon,player.profile);const detail=document.createElement('div');paintPlayerName(detail,player.profile,player.profile.name+(n===room.side?'（あなた）':''));const deck=document.createElement('small');deck.textContent=player.hidden?'編成は非公開（'+(room.ready?.[n]?'準備完了':'編成中')+'）':player.items.map(i=>i.char).join('・');detail.append(deck);row.append(icon,detail);}else row.textContent='友だちの参加を待っています。';box.append(row);}const finished=room.status==='finished',ready=!!room.ready?.[room.side],departed=room.departed;document.getElementById('btn-friend-rematch').hidden=!finished||departed||ready;document.getElementById('btn-friend-unready').hidden=!finished||departed||!ready;document.getElementById('friend-ready-status').textContent=departed?'相手またはあなたが退出しました。新しい部屋で対戦できます。':finished?`あなた：${ready?'準備完了':'準備待ち'} ／ 相手：${room.ready?.[1-room.side]?'準備完了':'準備待ち'}。双方が準備完了で次のバトルが始まります。`:room.status==='playing'?`第${room.round||1}戦・対局終了後に編成を変更して再戦できます。`:'';if(room.status==='waiting')setFriendStatus('参加待ち・合言葉の有効期限は作成から15分です。');}
async function ensurePlayerProfile(){const p=normalizedPlayerProfile(gameState.playerProfile);const result=await playerApi('/api/profile','PUT',{...p,achievementProgress:gameState.iconProgress});acceptHonorProgress(result.achievementProgress);gameState.playerProfile=result.profile;renderPlayerIdentity();saveState();}
window.createFriendRoom=async(friendCode)=>{if(friendBusy||friendRoom)return;setFriendLobbyTab('match');setFriendBusy(true);setFriendStatus('部屋を作成中…');try{await loadFriendSetup();const team=friendRoster();await ensurePlayerProfile();acceptFriendRoom(await playerApi('/api/friends/rooms','POST',{...team,ruleSet:friendEffectiveRule(),...(friendCode?{friendCode}:{})}),false);startFriendPolling();}catch(error){setFriendStatus(error.message);}finally{setFriendBusy(false);}};
window.joinFriendRoom=async()=>{if(friendBusy||friendRoom)return;setFriendLobbyTab('match');const code=document.getElementById('friend-room-code').value.trim().toUpperCase();if(!/^[A-Z2-9]{8}$/.test(code)){setFriendStatus('8文字の合言葉を入力してください。');return;}setFriendBusy(true);setFriendStatus('部屋に参加中…');try{const rules=await playerApi(`/api/friends/rooms/${code}/rules`);friendRuleSelected=rules.ruleSet;renderFriendRules();await loadFriendSetup();const team=friendRoster();await ensurePlayerProfile();acceptFriendRoom(await playerApi(`/api/friends/rooms/${code}/join`,'POST',team),false);startFriendPolling();}catch(error){setFriendStatus(error.message);}finally{setFriendBusy(false);}};
window.copyFriendCode=async()=>{if(!friendRoom)return;try{await navigator.clipboard.writeText(friendRoom.code);setFriendStatus('合言葉をコピーしました。');}catch{setFriendStatus('合言葉を長押ししてコピーできます。');}};
async function resumeFriendRoom(code){try{const room=await playerApi(`/api/friends/rooms/${code}`);if(room.status==='closed'){rememberFriendCode(null);return;}acceptFriendRoom(room,false);startFriendPolling();}catch(error){rememberFriendCode(code);document.getElementById('btn-friend-retry').hidden=false;setFriendStatus(error.message);}}
function friendShouldPoll(){return friendRoom&&['waiting','preparing','playing','finished'].includes(friendRoom.status)&&!(friendRoom.mode==='online'&&friendRoom.status==='finished');}
function friendPollDelay(){return KanjiNetwork.delay(friendRoom?.status==='playing'?1000:3000,friendPollFailures,5000);}
function startFriendPolling(){clearTimeout(friendTimer);if(friendShouldPoll()&&!document.hidden)friendTimer=setTimeout(pollFriendRoom,friendPollDelay());}
async function pollFriendRoom(){
 if(!friendShouldPoll()||document.hidden||friendPollBusy)return;friendPollBusy=true;clearTimeout(friendTimer);const code=friendRoom.code;
 try{const room=await playerApi(`/api/friends/rooms/${code}?since=${friendRoom.revision}`);if(friendRoom?.code!==code)return;
  if(room.unchanged){
   if(room.revision===friendRoom.revision){Object.assign(friendRoom,{deadline:room.deadline,graceUntil:room.graceUntil,serverNow:room.serverNow});
    if(!friendAnimating){if(friendPollFailed){if(friendRoom.state)finishFriendDisplay(friendRoom);else{renderFriendLobby();renderBattlePreparation();}}else if(friendRoom.mode==='online'&&friendRoom.state)renderOnlineClock(friendRoom);}
   }
  }else if(!friendAnimating)acceptFriendRoom(room,true);
  friendPollFailures=0;friendPollFailed=false;document.getElementById('btn-friend-retry').hidden=!friendPendingShot;
 }catch(error){if(friendRoom?.code!==code)return;friendPollFailures++;friendPollFailed=true;isPlayerTurn=false;document.getElementById('btn-friend-retry').hidden=false;setFriendStatus('通信が途切れています。再接続で盤面を確認できます。');}
 finally{friendPollBusy=false;startFriendPolling();}
}
window.reconnectFriendRoom=async()=>{if(friendBusy)return;setFriendBusy(true);try{if(friendPendingShot&&friendRoom){const room=await playerApi(`/api/friends/rooms/${friendRoom.code}/shot`,'POST',friendPendingShot);acceptFriendRoom(room,true);}else{const code=friendRoom?.code||sessionStorage.getItem('kanji_friend_room');if(code)acceptFriendRoom(await playerApi(`/api/friends/rooms/${code}`),false);else setFriendStatus('新しい部屋を作成してください。');}document.getElementById('btn-friend-retry').hidden=true;startFriendPolling();}catch(error){setFriendStatus(error.message);}finally{setFriendBusy(false);}};
function acceptFriendRoom(room,animate){const previous=friendRoom;if(previous&&room.code===previous.code&&room.revision<previous.revision)return;const newRound=previous&&room.code===previous.code&&room.round!==previous.round;friendRoom=room;window.recordFriendBattleActivations?.(room);if(newRound){abandonSoloReplay();friendAnimation++;friendAnimating=false;friendPendingShot=null;friendResultRevision=-1;document.getElementById('modal-result').classList.add('hidden');document.getElementById('modal-friend-deck').classList.add('hidden');friendDeckDraft=null;switchTab('battle');}rememberFriendCode(room.code);renderFriendLobby();renderFriendDirectory();if(room.status==='preparing'||room.status==='closed'&&battleMode==='friend'){const entering=previous?.status!=='preparing'||previous?.code!==room.code;battleMode='friend';soloBattlePending=false;endlessRun=null;specialChallenge=null;clearTimeout(cpuTurnTimer);clearTimeout(playerTurnTimer);cpuTurnTimer=null;playerTurnTimer=null;cancelDrag();isPlayerTurn=false;runner.enabled=false;document.getElementById('arena-container').classList.add('friend-arena');resizeArena();if(entering){friendResultRevision=-1;document.getElementById('modal-friends').classList.add('hidden');document.getElementById('modal-online').classList.add('hidden');document.getElementById('modal-result').classList.add('hidden');switchTab('battle');}renderBattlePreparation();return;}if(!room.state)return;
 soloBattlePending=false;renderBattlePreparation();
 if(friendPendingShot&&(room.state.lastShot?.id===friendPendingShot.id||room.revision>friendPendingShot.revision))friendPendingShot=null;
 if(battleMode!=='friend'){battleMode='friend';endlessRun=null;specialChallenge=null;clearTimeout(cpuTurnTimer);clearTimeout(playerTurnTimer);cancelDrag();document.getElementById('modal-result').classList.add('hidden');runner.enabled=false;document.getElementById('turn-banner').classList.add('scale-0');document.getElementById('arena-container').classList.add('friend-arena');switchTab('battle');resizeArena();friendResultRevision=-1;}
 document.getElementById('friend-battle-status').hidden=false;document.getElementById('endless-status').hidden=true;
 const me=room.side===0?room.host:room.guest,peer=room.side===0?room.guest:room.host;paintPlayerAvatar(document.getElementById('battle-self-icon'),me.profile);paintPlayerAvatar(document.getElementById('battle-peer-icon'),peer.profile);document.getElementById('battle-peer-icon').hidden=false;paintPlayerName(document.getElementById('battle-self-name'),me.profile);paintPlayerName(document.getElementById('cpu-name'),peer.profile);document.getElementById('cpu-rank').textContent=KanjiOnlineRules.description(KanjiOnlineRules.roomRule(room));
 const opening=room.state.opening;document.getElementById('battle-order-status').textContent=`総画数：あなた${room.side?opening.cpuTotal:opening.playerTotal}・相手${room.side?opening.playerTotal:opening.cpuTotal} / ${opening.tie?'抽選：':''}${(opening.playerFirst?0:1)===room.side?'あなた':'相手'}先攻`;
 if(previous&&(room.revision===previous.revision||!newRound&&previous.state?.finished&&room.state.finished)&&playerBodies.some(b=>b.gameData.friendKey!==undefined)){if(!friendAnimating)finishFriendDisplay(room);return;}
 buildFriendBodies(room);
 if(animate&&previous?.state&&room.state.replay&&room.state.lastShot&&previous.revision+1===room.revision&&!document.hidden){document.getElementById('modal-friends').classList.add('hidden');animateFriendReplay(room);}else{document.getElementById('modal-friends').classList.add('hidden');finishFriendDisplay(room);}
}
function buildFriendBodies(room){cancelDrag();clearShotSelection();Composite.clear(engine.world);playerBodies=[];cpuBodies=[];const flip=room.side===1;for(const piece of room.state.pieces){const d=JSON.parse(JSON.stringify(piece.data)),isPlayer=(piece.key<3?0:1)===room.side;d.isPlayer=isPlayer;d.friendKey=piece.key;const pos=flip?{x:400-piece.x,y:400-piece.y}:{x:piece.x,y:piece.y},b=KanjiTraits.createBody(d,pos.x,pos.y,1,KanjiRules.getPhysics(getKanjiStats(d)),piece.angle+(flip?Math.PI:0));b.gameData=d;Body.setMass(b,piece.mass);Body.setAngularVelocity(b,0);(isPlayer?playerBodies:cpuBodies).push(b);}battlePressure={...room.state.pressure};arenaRadius=184*battlePressure.ratio;arenaBaseRadius=184;arenaCenter={x:200,y:200};inspectedBody=null;hideBattleStats();resetMatchupFocus();isPlayerTurn=false;isBattleEnded=false;updateBattleCounters();updatePressureStatus();}
function setFriendFrame(room,frame){const flip=room.side===1;for(const body of [...playerBodies,...cpuBodies]){const p=frame[body.gameData.friendKey];Body.setPosition(body,{x:flip?400-p[0]:p[0],y:flip?400-p[1]:p[1]});Body.setAngle(body,p[2]+(flip?Math.PI:0));body.gameData.isOut=!!p[3];}updateBattleCounters();}
function animateFriendReplay(room){cancelDrag();friendAnimating=true;isPlayerTurn=false;const token=++friendAnimation,frames=room.state.replay.frames,start=performance.now();let eventIndex=0,lastFrame=-1;arenaRadius=184*(room.state.replay.ratioBefore||room.state.pressure.ratio);setFriendStatus('発射中…');playSound('launch');
 function tick(time){if(token!==friendAnimation||battleMode!=='friend')return;const fraction=Math.min(1,(time-start)/2200),index=fraction*(frames.length-1),left=Math.floor(index),right=Math.min(frames.length-1,left+1),mix=index-left;const frame=frames[left].map((p,n)=>p.map((value,k)=>k===3?value:value+(frames[right][n][k]-value)*mix));setFriendFrame(room,frame);
  if(left!==lastFrame){for(const b of [...playerBodies,...cpuBodies])if(b.gameData.friendKey===room.state.lastShot.key)Body.setAngularVelocity(b,room.state.lastShot.spin?Math.sign(room.state.lastShot.spin)*.02:0);lastFrame=left;}
  const events=room.state.replay.events;while(eventIndex<events.length&&events[eventIndex].tick<=fraction*132){const e=events[eventIndex++],b=[...playerBodies,...cpuBodies].find(b=>b.gameData.friendKey===e.key);if(b&&!b.gameData.isOut)showAbilityActivation(b,e);}
  if(fraction<1&&!document.hidden)requestAnimationFrame(tick);else{friendAnimating=false;for(const b of [...playerBodies,...cpuBodies])Body.setAngularVelocity(b,0);finishFriendDisplay(room);startFriendPolling();}}
 requestAnimationFrame(tick);
}
function finishFriendDisplay(room){if(friendAnimating)return;acceptRoomReplay(room);document.getElementById('btn-online-result-next').hidden=true;const frame=room.state.pieces.map(p=>[p.x,p.y,p.angle,p.data.isOut?1:0]);setFriendFrame(room,frame);battlePressure={...room.state.pressure};arenaRadius=184*battlePressure.ratio;updatePressureStatus();isBattleEnded=room.state.finished;isPlayerTurn=!isBattleEnded&&!friendPendingShot&&room.state.turn===room.side;updateCentralShotStatus();document.getElementById('battle-turn-label').dataset.team=isPlayerTurn?'ally':'enemy';const text=isBattleEnded?'対局終了':friendPendingShot?'発射の受付を確認中…':isPlayerTurn?'あなたの番':'相手の番';setFriendStatus(text);if(room.mode==='online'&&typeof renderOnlineBattle==='function')renderOnlineBattle(room);document.getElementById('battle-turn-label').textContent=text;document.getElementById('battle-guide-text').textContent=isPlayerTurn?'文字を選び、点線内の空き場所を引いて発射・回転も使用できます':isBattleEnded?'対局終了・「部屋」で編成を変えて何度でも再戦できます':'相手の発射を待っています';document.getElementById('btn-friend-next').hidden=!isBattleEnded||room.departed;document.getElementById('btn-friend-result-deck').hidden=!isBattleEnded||room.departed;document.getElementById('btn-friend-next').disabled=!!room.ready?.[room.side]||friendBusy;document.getElementById('btn-result-room-exit').hidden=!isBattleEnded;if(isBattleEnded&&friendResultRevision!==room.round){friendResultRevision=room.round;recordFriendUsage(room);document.getElementById('btn-practice-retry').hidden=true;const win=room.state.winner===room.side,draw=room.state.winner===null;document.getElementById('result-title-badge').textContent=draw?'引き分け':win?'勝 利':'敗 北';document.getElementById('result-message').textContent=room.state.reason==='退出'?'相手が退出したため対局を終了しました。':`${room.state.reason==='全滅'?'文字コマの全滅':room.state.reason}で決着しました。`;document.getElementById('result-rp-change').textContent='変動なし';document.getElementById('result-coin-change').textContent='変動なし';document.getElementById('result-exp-info').hidden=true;document.getElementById('btn-endless-next').hidden=true;document.getElementById('btn-special-retry').hidden=true;document.getElementById('btn-special-next').hidden=true;document.getElementById('btn-result-close').textContent='部屋に戻る';document.getElementById('modal-result').classList.remove('hidden');if(room.mode==='online')renderOnlineResult(room);playSound(win?'win':'lose');}}
window.launchFriendShot=(body,vector,magnitude,spin=0)=>{if(friendAnimating||friendPendingShot||friendBusy||battleMode!=='friend'||isBattleEnded||!isPlayerTurn||battleInputMode!=='shoot'||!body?.gameData?.isPlayer||body.gameData.isOut||!playerBodies.includes(body)||!friendRoom||!Number.isFinite(magnitude)||magnitude<=0)return false;const side=friendRoom.side,sign=side===0?1:-1,shot={id:playerRandomId(),revision:friendRoom.revision,key:body.gameData.friendKey,dx:vector.x*sign,dy:vector.y*sign,power:Math.min(120,magnitude)/120,spin:KanjiTraits.normalizeSpin(spin)};shotSpin=shot.spin;clearShotSelection();friendPendingShot=shot;isPlayerTurn=false;cancelDrag();setFriendStatus('発射を送信中…');playerApi(`/api/friends/rooms/${friendRoom.code}/shot`,'POST',shot).then(room=>acceptFriendRoom(room,true)).catch(async error=>{document.getElementById('btn-friend-retry').hidden=false;setFriendStatus(error.message+' 再接続で受付を確認できます。');if(error.status===409){friendPendingShot=null;try{acceptFriendRoom(await playerApi(`/api/friends/rooms/${friendRoom.code}`),false);}catch{}}});return true;};
window.leaveFriendRoom=async()=>{if(friendBusy)return;if(friendRoom?.mode==='online'&&['preparing','playing'].includes(friendRoom.status)&&!friendRoom.departed){showToast('マッチ成立後は対局終了まで退出できません。');return;}setFriendBusy(true);try{if(friendRoom){try{await playerApi(`/api/friends/rooms/${friendRoom.code}/leave`,'POST',{});}catch(error){if(error.status!==404)throw error;}}clearTimeout(friendTimer);friendAnimation++;friendAnimating=false;friendPendingShot=null;friendRoom=null;rememberFriendCode(null);document.getElementById('btn-friend-retry').hidden=true;document.getElementById('modal-result').classList.add('hidden');if(battleMode==='friend'){battleMode='classic';resetBattle();renderPlayerIdentity();}renderFriendLobby();setFriendStatus('退出しました。新しい部屋を作成できます。');}catch(error){setFriendStatus(error.message+' 通信が戻ったら再度退出してください。');}finally{setFriendBusy(false);}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(friendTimer);if(friendAnimating){friendAnimation++;friendAnimating=false;if(friendRoom?.state)finishFriendDisplay(friendRoom);}}else if(friendShouldPoll())pollFriendRoom();});
window.addEventListener('online',()=>{queueHonorSync();if(friendRoom)reconnectFriendRoom();});

function repaintAvatarFonts(){avatarInkCache.clear();document.querySelectorAll('.player-avatar').forEach(drawAvatarGlyph);}
document.fonts.ready.then(repaintAvatarFonts);document.fonts.addEventListener('loadingdone',repaintAvatarFonts);

window.exitCurrentRoom=async()=>{if(!friendRoom||friendBusy||onlineBusy)return;const online=friendRoom.mode==='online';if(online){await leaveOnlineMatch();if(friendRoom)showToast('退出できませんでした。通信を確認して、もう一度お試しください。');return;}await leaveFriendRoom();if(friendRoom){showToast('退出できませんでした。通信を確認して、もう一度お試しください。');return;}document.getElementById('modal-battle-menu').classList.add('hidden');switchTab('matches');openFriendLobby();};
